"""Project-authored, deterministic PCM foley. No cloud service or sampled external recording."""
import math,random,wave,struct,json,hashlib,pathlib
root=pathlib.Path(__file__).resolve().parents[3];out=root/'src/chapter2/presentation/audio';out.mkdir(parents=True,exist_ok=True)
rate=24000;rows=[]
settings={'cast':(.65,.15,'Air and line movement'),'bobber':(.2,.13,'Small water plop'),'reel':(1.0,.10,'Line rubbing wood'),'splash':(.85,.18,'Water noise with drops'),'wheel':(1.2,.12,'Wooden wheel rolling'),'coin':(.5,.12,'Two restrained metal ticks'),'steam':(1.1,.08,'Soft steam release'),'bell':(1.2,.12,'Tongued bell only; NEVER the silent story bell')}
for seed,(name,(length,target,description)) in enumerate(settings.items()):
 rnd=random.Random(900+seed);smooth=0;data=[]
 for i in range(int(rate*length)):
  t=i/rate;n=rnd.uniform(-1,1);smooth=.78*smooth+.22*n;env=min(1,t/.012)*min(1,(length-t)/.07)
  if name=='cast':v=(.5*smooth+.2*n)*math.sin(math.pi*t/length)**1.6
  elif name=='bobber':v=math.sin(2*math.pi*(300*t-120*t*t))*math.exp(-24*t)+smooth*.3*math.exp(-18*t)
  elif name=='reel':v=smooth*(.6+.35*math.sin(2*math.pi*11*t))+.025*math.sin(2*math.pi*85*t)
  elif name=='splash':v=(smooth+.2*n)*math.exp(-3.2*t)+.15*math.sin(2*math.pi*690*t)*math.exp(-12*t)
  elif name=='wheel':v=smooth*.35*(.7+.3*math.cos(2*math.pi*7*t))+.17*math.sin(2*math.pi*(100*t+1.6*math.sin(t*13)))*math.sin(math.pi*t/length)
  elif name=='coin':v=sum(math.sin(2*math.pi*f*(t-offset))*math.exp(-18*(t-offset)) for offset in [0,.16] for f in [1650,2417] if t>=offset)*.4
  elif name=='steam':v=(n-smooth)*math.sin(math.pi*t/length)**.8*.3
  else:v=sum(math.sin(2*math.pi*f*t)*math.exp(-d*t)*a for f,d,a in [(770,3,1),(1193,4,.35),(2094,5,.14)])
  data.append(v*env)
 peak=max(map(abs,data));data=[v*target/peak for v in data];p=out/(name+'.wav')
 with wave.open(str(p),'wb') as f:f.setnchannels(1);f.setsampwidth(2);f.setframerate(rate);f.writeframes(b''.join(struct.pack('<h',round(v*32767)) for v in data))
 rows.append({'id':name,'file':'audio/'+name+'.wav','sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'seconds':length,'peak':target,'rms':(sum(v*v for v in data)/len(data))**.5,'source':'09 deterministic DSP, generated by generate-foley.py','rights':'Project-authored synthesis; no external samples or cloud purchase','description':description})
for id,p,gain,offset,duration in [('rope_test',root/'public/assets/hongqiao/cinema/audio/sfx_rope_handle.wav',.22,.1,.7),('tea_pour',root/'public/assets/audio/street/sfx/SFX_02_QMSH-17_street-166_pour_water_v01.wav',.2,0,1.2),('cup_set',root/'public/assets/audio/street/sfx/SFX_02_QMSH-17_street-166_tea_cup_v01.wav',.18,0,.65)]:
 rows.append({'id':id,'file':str(p.relative_to(root/'public')),'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'source':'Existing user-provided project sound','rights':'Existing in-project use authorized by task; no new external redistribution license inferred','gain':gain,'offset':offset,'duration':duration})
ambient=root/'public/assets/audio/ambience/spring_riverside_loop_30s.wav'
manifest={'version':1,'sampleRate':rate,'noCloudPurchase':True,'dialogue':'Formal original Chinese subtitles, not TTS or reused first-chapter voice','silentBellPolicy':'treasure_c2_silent_bell never rings; bell cue requires explicit audibleBell=true','files':rows,'ambience':{'file':'assets/audio/ambience/spring_riverside_loop_30s.wav','sha256':hashlib.sha256(ambient.read_bytes()).hexdigest(),'sourceManifest':'public/assets/audio/ambience/source.json','implementation':'Borrow existing host decoded buffer; restore host ambience after own lease ends'},'mix':{'maxVoices':2,'ambienceGain':.035,'effectGain':.4,'automaticVoiceShouts':0}}
(root/'src/chapter2/presentation/sound-manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n')
print('created',len(settings),'non-silent PCM files; reused',3,'effects and existing ambience')
